CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts(id text PRIMARY KEY, roles jsonb NOT NULL DEFAULT '["client","creator","lender"]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id_hash text PRIMARY KEY, account_id text NOT NULL REFERENCES accounts(id), book text NOT NULL CHECK(book IN ('SIMULATION','TESTNET')), csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE auth_nonces(id uuid PRIMARY KEY, nonce text NOT NULL, message text NOT NULL, recipient text NOT NULL, expires_at timestamptz NOT NULL, consumed boolean NOT NULL DEFAULT false);
CREATE TABLE agents(id text NOT NULL, book text NOT NULL CHECK(book IN ('SIMULATION','TESTNET')), owner_id text NOT NULL REFERENCES accounts(id), name text NOT NULL, category text NOT NULL, state text NOT NULL DEFAULT 'ACTIVE', data jsonb NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(id,book));
CREATE TABLE agent_versions(agent_id text NOT NULL, book text NOT NULL, version integer NOT NULL, manifest jsonb NOT NULL, hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(agent_id,book,version), FOREIGN KEY(agent_id,book) REFERENCES agents(id,book));
CREATE TABLE execution_policies(agent_id text NOT NULL, book text NOT NULL, owner_id text NOT NULL REFERENCES accounts(id), data jsonb NOT NULL, version integer NOT NULL DEFAULT 1, PRIMARY KEY(agent_id,book), FOREIGN KEY(agent_id,book) REFERENCES agents(id,book));
CREATE TABLE jobs(id uuid PRIMARY KEY, book text NOT NULL CHECK(book IN ('SIMULATION','TESTNET')), client_id text NOT NULL REFERENCES accounts(id), parent_id uuid, agent_id text, state text NOT NULL CHECK(state IN ('OPEN','FUNDED','RUNNING','DELIVERED','REVISION_REQUIRED','REVIEW_OPEN','DISPUTED','SETTLED','REFUNDED','CANCELLED')), data jsonb NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,book), FOREIGN KEY(parent_id,book) REFERENCES jobs(id,book), FOREIGN KEY(agent_id,book) REFERENCES agents(id,book));
CREATE INDEX jobs_owner ON jobs(book,client_id,created_at DESC);
CREATE TABLE bids(id uuid PRIMARY KEY, job_id uuid NOT NULL, agent_id text NOT NULL, book text NOT NULL, amount text NOT NULL CHECK(amount ~ '^[0-9]+$'), data jsonb NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(job_id,agent_id), FOREIGN KEY(job_id,book) REFERENCES jobs(id,book), FOREIGN KEY(agent_id,book) REFERENCES agents(id,book));
CREATE TABLE funding_previews(id uuid PRIMARY KEY, job_id uuid NOT NULL REFERENCES jobs(id), actor text NOT NULL, payload_hash text NOT NULL, data jsonb NOT NULL, expires_at timestamptz NOT NULL, consumed boolean NOT NULL DEFAULT false);
CREATE TABLE balances(book text NOT NULL CHECK(book IN ('SIMULATION','TESTNET')), account_id text NOT NULL, bucket text NOT NULL, amount numeric(78,0) NOT NULL DEFAULT 0 CHECK(amount>=0), PRIMARY KEY(book,account_id,bucket));
CREATE TABLE ledger_entries(id bigserial PRIMARY KEY, transfer_id uuid NOT NULL, book text NOT NULL, account_id text NOT NULL, bucket text NOT NULL, delta numeric(78,0) NOT NULL CHECK(delta<>0), job_id uuid REFERENCES jobs(id), reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ledger_account ON ledger_entries(book,account_id,id DESC);
CREATE TABLE deliveries(id uuid PRIMARY KEY, job_id uuid NOT NULL REFERENCES jobs(id), revision integer NOT NULL, content jsonb NOT NULL, hash text NOT NULL, checks jsonb NOT NULL, ai jsonb NOT NULL DEFAULT '{"result":"UNAVAILABLE"}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(job_id,revision));
CREATE TABLE job_events(id bigserial PRIMARY KEY, job_id uuid NOT NULL REFERENCES jobs(id), actor text NOT NULL, type text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE disputes(id uuid PRIMARY KEY, job_id uuid NOT NULL UNIQUE REFERENCES jobs(id), actor text NOT NULL, reason text NOT NULL, evidence_hash text NOT NULL, deadline timestamptz NOT NULL, decision jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE runs(id text PRIMARY KEY, job_id uuid NOT NULL REFERENCES jobs(id), agent_id text NOT NULL, state text NOT NULL, data jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_jobs(id uuid PRIMARY KEY, job_id uuid NOT NULL REFERENCES jobs(id), type text NOT NULL, data jsonb NOT NULL DEFAULT '{}', attempts integer NOT NULL DEFAULT 0, state text NOT NULL DEFAULT 'QUEUED', lease_until timestamptz, next_attempt timestamptz NOT NULL DEFAULT now(), error text, UNIQUE(job_id,type));
CREATE TABLE idempotency(account_id text NOT NULL, key text NOT NULL, hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(account_id,key));
CREATE TABLE chain_operations(id uuid PRIMARY KEY, request_id text NOT NULL UNIQUE, account_id text NOT NULL, job_id uuid REFERENCES jobs(id), state text NOT NULL, payload_hash text NOT NULL, proposal jsonb NOT NULL, tx_hash text, receipt jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE chain_events(receipt_id text NOT NULL, event_index integer NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(receipt_id,event_index));
CREATE TABLE audit_log(id bigserial PRIMARY KEY, actor text NOT NULL, action text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE price_snapshots(id text PRIMARY KEY, mode text NOT NULL, price text NOT NULL CHECK(price ~ '^[0-9]+$'), published_at timestamptz NOT NULL, data jsonb NOT NULL);
CREATE TABLE pool_epochs(id uuid PRIMARY KEY, book text NOT NULL DEFAULT 'SIMULATION' CHECK(book='SIMULATION'), state text NOT NULL CHECK(state IN ('FUNDRAISING','LENDING','REDEMPTION','CLOSED')), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pool_shares(epoch_id uuid NOT NULL REFERENCES pool_epochs(id), account_id text NOT NULL REFERENCES accounts(id), shares numeric(78,0) NOT NULL CHECK(shares>=0), redeemed boolean NOT NULL DEFAULT false, PRIMARY KEY(epoch_id,account_id));
CREATE TABLE loans(id uuid PRIMARY KEY, book text NOT NULL DEFAULT 'SIMULATION' CHECK(book='SIMULATION'), owner_id text NOT NULL REFERENCES accounts(id), job_id uuid NOT NULL UNIQUE REFERENCES jobs(id), child_id uuid NOT NULL UNIQUE REFERENCES jobs(id), epoch_id uuid NOT NULL REFERENCES pool_epochs(id), state text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
